const readline = require('readline');

const letters = 'abcdefghijklmnopqrstuvwxyz';
const digits =  '22233344455566677778889999';
const map = {};
for (let i = 0; i < 26; i++) map[letters[i]] = digits[i];

const rl = readline.createInterface({ input: process.stdin });
const lines = [];
rl.on('line', (l) => lines.push(l.trim()));
rl.on('close', () => {
  const N = lines[0];
  const M = parseInt(lines[1], 10);
  let count = 0;
  for (let i = 0; i < M; i++) {
    const s = lines[2 + i];
    if (s.length !== N.length) continue;
    let ok = true;
    for (let j = 0; j < s.length; j++) {
      if (map[s[j]] !== N[j]) { ok = false; break; }
    }
    if (ok) count++;
  }
  console.log(count);
});
